167	console.log('\n🚀 To publish, run:');
168	console.log('   npm login');
169	console.log('   cd v3 && npm run build');
170	for (const pkg of publishOrder) {
171	  console.log(`   cd @claude-flow/${pkg} && npm publish --tag v3alpha && cd ../..`);
172	}
173	console.log('   cd claude-flow && npm publish --tag v3alpha');
