1	#!/usr/bin/env node
2	/**
3	 * Claude Flow Memory Helper
4	 * Simple key-value memory for cross-session context
5	 */
6	
7	const fs = require('fs');
8	const path = require('path');
9	
10	const MEMORY_DIR = path.join(process.cwd(), '.claude-flow', 'data');
11	const MEMORY_FILE = path.join(MEMORY_DIR, 'memory.json');
12	
13	function loadMemory() {
14	  try {
15	    if (fs.existsSync(MEMORY_FILE)) {
16	      return JSON.parse(fs.readFileSync(MEMORY_FILE, 'utf-8'));
17	    }
18	  } catch (e) {
19	    // Ignore
20	  }
21	  return {};
22	}
23	
24	function saveMemory(memory) {
25	  fs.mkdirSync(MEMORY_DIR, { recursive: true });
26	  fs.writeFileSync(MEMORY_FILE, JSON.stringify(memory, null, 2));
27	}
28	
29	const commands = {
30	  get: (key) => {
31	    const memory = loadMemory();
32	    const value = key ? memory[key] : memory;
33	    console.log(JSON.stringify(value, null, 2));
34	    return value;
35	  },
36	
37	  set: (key, value) => {
38	    if (!key) {
39	      console.error('Key required');
40	      return;
41	    }
42	    const memory = loadMemory();
43	    memory[key] = value;
44	    memory._updated = new Date().toISOString();
45	    saveMemory(memory);
46	    console.log(`Set: ${key}`);
47	  },
48	
49	  delete: (key) => {
50	    if (!key) {
51	      console.error('Key required');
52	      return;
53	    }
54	    const memory = loadMemory();
55	    delete memory[key];
56	    saveMemory(memory);
57	    console.log(`Deleted: ${key}`);
58	  },
59	
60	  clear: () => {
61	    saveMemory({});
62	    console.log('Memory cleared');
63	  },
64	
65	  keys: () => {
66	    const memory = loadMemory();
67	    const keys = Object.keys(memory).filter(k => !k.startsWith('_'));
68	    console.log(keys.join('\n'));
69	    return keys;
70	  },
71	};
72	
73	// CLI
74	const [,, command, key, ...valueParts] = process.argv;
75	const value = valueParts.join(' ');
76	
77	if (command && commands[command]) {
78	  commands[command](key, value);
79	} else {
80	  console.log('Usage: memory.js <get|set|delete|clear|keys> [key] [value]');
81	}
82	
83	module.exports = commands;
84

1	#!/usr/bin/env node
2	/**
3	 * Claude Flow Session Manager
4	 * Handles session lifecycle: start, restore, end
5	 */
6	
7	const fs = require('fs');
8	const path = require('path');
9	
10	const SESSION_DIR = path.join(process.cwd(), '.claude-flow', 'sessions');
11	const SESSION_FILE = path.join(SESSION_DIR, 'current.json');
12	
13	const commands = {
14	  start: () => {
15	    const sessionId = `session-${Date.now()}`;
16	    const session = {
17	      id: sessionId,
18	      startedAt: new Date().toISOString(),
19	      cwd: process.cwd(),
20	      context: {},
21	      metrics: {
22	        edits: 0,
23	        commands: 0,
24	        tasks: 0,
25	        errors: 0,
26	      },
27	    };
28	
29	    fs.mkdirSync(SESSION_DIR, { recursive: true });
30	    fs.writeFileSync(SESSION_FILE, JSON.stringify(session, null, 2));
31	
32	    console.log(`Session started: ${sessionId}`);
33	    return session;
34	  },
35	
36	  restore: () => {
37	    if (!fs.existsSync(SESSION_FILE)) {
38	      console.log('No session to restore');
39	      return null;
40	    }
41	
42	    const session = JSON.parse(fs.readFileSync(SESSION_FILE, 'utf-8'));
43	    session.restoredAt = new Date().toISOString();
44	    fs.writeFileSync(SESSION_FILE, JSON.stringify(session, null, 2));
