7	const fs = require('fs');
8	const path = require('path');
9	
10	const SESSION_DIR = path.join(process.cwd(), '.claude-flow', 'sessions');
11	const SESSION_FILE = path.join(SESSION_DIR, 'current.json');
12	
13	// #2307: Atomic write — serialize to a per-process temp file, then rename()
14	// into place. rename() is atomic on the same filesystem, so concurrent writers
15	// (session-restore, metric, daemon workers, teammates) can't interleave partial
16	// content. Without this, two non-atomic writeFileSync calls can race so that a
17	// shorter payload overwrites a longer one in place, leaving the longer payload's
18	// tail dangling past the end (valid JSON + trailing garbage = parse error).
19	// Temp name includes process.pid so concurrent writers don't collide on it.
20	// Same class as #1707 (metrics) / #1637 (daemon-state) — session.js was missed.
21	function atomicWrite(file, data) {
22	  const tmp = `${file}.tmp.${process.pid}`;
23	  fs.writeFileSync(tmp, data);
24	  fs.renameSync(tmp, file);
25	}
26	
